// Prepare a zero-initialized RAROpenArchiveData with required fields.
RAROpenArchiveData od = {};

// Provide a valid archive path (existing temp file with random data)
const char *path = FUZZ_PARAM_FILENAME();
od.ArcName = (char *)path; // API expects char*; temp file path is null-terminated

// Choose a valid open mode among documented constants
unsigned int modePick = *FUZZ_PARAM(unsigned int) % 3;
switch (modePick) {
  case 0: od.OpenMode = RAR_OM_LIST; break;
  case 1: od.OpenMode = RAR_OM_EXTRACT; break;
  default: od.OpenMode = RAR_OM_LIST_INCSPLIT; break;
}

// Optionally enable comment retrieval with a bounded writable buffer
unsigned int wantCmt = *FUZZ_PARAM(unsigned int) & 1U;
std::string cmtBufStr = FUZZ_PARAM_STR();
if (cmtBufStr.size() > 512) cmtBufStr.resize(512);
// Ensure at least 1 byte if enabled
if (wantCmt && cmtBufStr.size() == 0) cmtBufStr.resize(1);
std::vector<char> cbuf(wantCmt ? cmtBufStr.size() : 0);
if (wantCmt) {
  memcpy(cbuf.data(), cmtBufStr.data(), cbuf.size());
  od.CmtBuf = cbuf.data();
  od.CmtBufSize = (unsigned int)cbuf.size();
}

// Call the target function
auto hArcData = RAROpenArchive(&od);

// Validate: must return non-null handle on success
if (!hArcData) { FUZZ_BAIL(); }

// Track handle state for downstream API usage
FUZZ_SET_ATTR_INT(hArcData, "open", 1);
FUZZ_SET_ATTR_INT(hArcData, "have_header", 0);
FUZZ_SET_ATTR_INT(hArcData, "openmode", (int)od.OpenMode);
// Return the handle as persistent output

// Prepare a zero-initialized RAROpenArchiveDataEx with required fields.
RAROpenArchiveDataEx od = {};

// Choose ANSI or Wide name (at least one must be set)
unsigned int wide = *FUZZ_PARAM(unsigned int) & 1U;
const char *path = FUZZ_PARAM_FILENAME();
od.ArcName = wide ? (char*)nullptr : (char*)path;

// If wide selected, build a simple wide version (byte-wise widen)
std::wstring wpath;
if (wide) {
  std::string sp(path);
  wpath.assign(sp.begin(), sp.end());
  wpath.push_back(L'\0');
  od.ArcNameW = (wchar_t*)wpath.c_str();
}

// Valid open mode
unsigned int modePick = *FUZZ_PARAM(unsigned int) % 3;
switch (modePick) {
  case 0: od.OpenMode = RAR_OM_LIST; break;
  case 1: od.OpenMode = RAR_OM_EXTRACT; break;
  default: od.OpenMode = RAR_OM_LIST_INCSPLIT; break;
}

// Optional comment buffers (ANSI and/or Wide), bounded in size
unsigned int wantCmtA = *FUZZ_PARAM(unsigned int) & 1U;
unsigned int wantCmtW = *FUZZ_PARAM(unsigned int) & 1U;

std::string cmtA = FUZZ_PARAM_STR();
if (cmtA.size() > 512) cmtA.resize(512);
std::vector<char> cbufA(wantCmtA ? cmtA.size() : 0);
if (wantCmtA && !cbufA.empty()) {
  memcpy(cbufA.data(), cmtA.data(), cbufA.size());
  od.CmtBuf = cbufA.data();
  od.CmtBufSize = (unsigned int)cbufA.size();
}

std::string cmtWsrc = FUZZ_PARAM_STR();
if (cmtWsrc.size() > 512) cmtWsrc.resize(512);
std::wstring cmtW;
if (wantCmtW) { cmtW.assign(cmtWsrc.begin(), cmtWsrc.end()); }
std::vector<wchar_t> cbufW(wantCmtW ? (cmtW.size() ? cmtW.size() : 1) : 0);
if (wantCmtW && !cbufW.empty()) {
  if (!cmtW.empty()) memcpy(cbufW.data(), cmtW.data(), cbufW.size()*sizeof(wchar_t));
  od.CmtBufW = cbufW.data();
}

// Explicitly disable callbacks for safety in this harness (no function pointers available)
od.Callback = (UNRARCALLBACK)0;
od.UserData = (LPARAM)0;

// Optionally set OpFlags with a random value (kept small)
od.OpFlags = *FUZZ_PARAM(unsigned int) & 0x7U; // small bitmask

// Call the target function
auto hArcData = RAROpenArchiveEx(&od);

// Validate: must succeed with a non-null handle
if (!hArcData) { FUZZ_BAIL(); }

// Track handle state
FUZZ_SET_ATTR_INT(hArcData, "open", 1);
FUZZ_SET_ATTR_INT(hArcData, "have_header", 0);
FUZZ_SET_ATTR_INT(hArcData, "openmode", (int)od.OpenMode);

// Validate handle state and single-close rule
int is_open = FUZZ_GET_ATTR_INT(hArcData, "open");
if (!is_open) { FUZZ_BAIL(); }

// Close and mark as closed
int rc = RARCloseArchive(hArcData);
(void)rc; // Caller may inspect ERAR_*; we only enforce API usage here
FUZZ_SET_ATTR_INT(hArcData, "open", 0);
FUZZ_SET_ATTR_INT(hArcData, "have_header", 0);
// Do not return the handle; dropping it from outputs releases it back to pool as closed

// Validate prerequisites: open handle
if (!FUZZ_GET_ATTR_INT(hArcData, "open")) { FUZZ_BAIL(); }

// Prepare a writable header structure (zeroed)
RARHeaderData hd = {};

// Invoke the target function
int rc = RARReadHeader(hArcData, &hd);

// Interpret result: ERAR_SUCCESS is 0; ERAR_END_ARCHIVE indicates no more entries
if (rc == 0) {
  // A header was read; mark current-entry state for ProcessFile
  FUZZ_SET_ATTR_INT(hArcData, "have_header", 1);
} else {
  // On non-success, clear the current-entry state
  FUZZ_SET_ATTR_INT(hArcData, "have_header", 0);
}

// Keep handle alive

// Validate prerequisites: open handle
if (!FUZZ_GET_ATTR_INT(hArcData, "open")) { FUZZ_BAIL(); }

// Prepare a writable extended header structure (zeroed)
RARHeaderDataEx hdx = {};

// Invoke the target function
int rc = RARReadHeaderEx(hArcData, &hdx);

// Track whether a header is available for processing
if (rc == 0) {
  FUZZ_SET_ATTR_INT(hArcData, "have_header", 1);
} else {
  FUZZ_SET_ATTR_INT(hArcData, "have_header", 0);
}

// Keep handle alive

// Validate: must be open and have a current header from a prior RARReadHeader/Ex
if (!FUZZ_GET_ATTR_INT(hArcData, "open")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hArcData, "have_header")) { FUZZ_BAIL(); }

// Choose an operation among documented values
int opPick = (int)(*FUZZ_PARAM(unsigned int) % 3);
int operation = (opPick == 0) ? RAR_SKIP : (opPick == 1) ? RAR_TEST : RAR_EXTRACT;

// DestPath/DestName are only required/used for extract; NULL is fine for skip/test
char *destPath = nullptr;
char *destName = nullptr;
if (operation == RAR_EXTRACT) {
  std::string p = FUZZ_PARAM_STR();
  std::string n = FUZZ_PARAM_STR();
  // Keep sizes modest
  if (p.size() > 256) p.resize(256);
  if (n.size() > 256) n.resize(256);
  destPath = p.empty() ? nullptr : (char*)p.c_str();
  destName = n.empty() ? nullptr : (char*)n.c_str();
  // Call immediately while strings are in scope
  int rc = RARProcessFile(hArcData, operation, destPath, destName);
  (void)rc;
} else {
  int rc = RARProcessFile(hArcData, operation, nullptr, nullptr);
  (void)rc;
}

// After processing, the current header is consumed
FUZZ_SET_ATTR_INT(hArcData, "have_header", 0);

// Validate: must be open and have a current header from a prior RARReadHeader/Ex
if (!FUZZ_GET_ATTR_INT(hArcData, "open")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(hArcData, "have_header")) { FUZZ_BAIL(); }

// Choose operation
int opPick = (int)(*FUZZ_PARAM(unsigned int) % 3);
int operation = (opPick == 0) ? RAR_SKIP : (opPick == 1) ? RAR_TEST : RAR_EXTRACT;

wchar_t *wDestPath = nullptr;
wchar_t *wDestName = nullptr;

if (operation == RAR_EXTRACT) {
  // Build modest-size wide strings
  std::string ps = FUZZ_PARAM_STR(); if (ps.size() > 256) ps.resize(256);
  std::string ns = FUZZ_PARAM_STR(); if (ns.size() > 256) ns.resize(256);
  std::wstring pw(ps.begin(), ps.end());
  std::wstring nw(ns.begin(), ns.end());
  wDestPath = pw.empty() ? nullptr : (wchar_t*)pw.c_str();
  wDestName = nw.empty() ? nullptr : (wchar_t*)nw.c_str();
  int rc = RARProcessFileW(hArcData, operation, wDestPath, wDestName);
  (void)rc;
} else {
  int rc = RARProcessFileW(hArcData, operation, nullptr, nullptr);
  (void)rc;
}

// Header consumed after processing
FUZZ_SET_ATTR_INT(hArcData, "have_header", 0);

// Set or clear a general callback. We do not install executable callbacks in this harness.
if (!FUZZ_GET_ATTR_INT(hArcData, "open")) { FUZZ_BAIL(); }

// Randomly choose to clear the callback (safe) or leave as NULL
unsigned int setNull = 1; // enforce NULL for safety
UNRARCALLBACK cb = (UNRARCALLBACK)0;
LPARAM userData = (LPARAM)(*FUZZ_PARAM(unsigned int));
RARSetCallback(hArcData, cb, userData);

// Keep handle persistent

// Register or clear legacy change-volume callback. We only clear (NULL) for safety.
if (!FUZZ_GET_ATTR_INT(hArcData, "open")) { FUZZ_BAIL(); }

CHANGEVOLPROC cv = (CHANGEVOLPROC)0; // disable
RARSetChangeVolProc(hArcData, cv);

// Register or clear legacy process-data callback. We only clear (NULL) for safety.
if (!FUZZ_GET_ATTR_INT(hArcData, "open")) { FUZZ_BAIL(); }

PROCESSDATAPROC pd = (PROCESSDATAPROC)0; // disable
RARSetProcessDataProc(hArcData, pd);

// Set or clear password prior to reading encrypted headers or files
if (!FUZZ_GET_ATTR_INT(hArcData, "open")) { FUZZ_BAIL(); }

// Use a fuzzed string (may be empty) as password; keep size reasonable
std::string pw = FUZZ_PARAM_STR();
if (pw.size() > 256) pw.resize(256);
char *p = pw.empty() ? (char*)nullptr : (char*)pw.c_str();
RARSetPassword(hArcData, p);

// Call version getter; assert it returns a positive integer interface version
int ver = RARGetDllVersion();
FUZZ_ASSERT(ver > 0, "RARGetDllVersion must be positive");

