import random
import struct

# Generate valid UTF-16LE (wchar_t on Windows) strings for use as archive names,
# destination paths, and destination names in the UNRAR fuzz stubs.
# We produce bytes that could be consumed by FUZZ_PARAM_FILENAME (ANSI path)
# or FUZZ_PARAM_STR and then widened by the harness. We keep output <= 4096 bytes.

MAX_BYTES = 4096

def _u16le(s: str, nul_terminated: bool = True) -> bytes:
    b = s.encode('utf-16le')
    return b + (b"\x00\x00" if nul_terminated else b"")

def _weighted_choice(rng: random.Random, items):
    total = sum(w for w, _ in items)
    pick = rng.uniform(0.0, total)
    acc = 0.0
    for w, v in items:
        acc += w
        if pick <= acc:
            return v
    return items[-1][1]

def _random_unicode_segment(rng: random.Random, min_len=1, max_len=20) -> str:
    length = rng.randint(min_len, max_len)
    pools = [
        (4, (0x0021, 0x007E)),   # printable ASCII
        (2, (0x00A1, 0x00FF)),   # Latin-1 supplement
        (2, (0x0400, 0x04FF)),   # Cyrillic
        (3, (0x4E00, 0x9FFF)),   # CJK Unified Ideographs
        (1, (0x3040, 0x309F)),   # Hiragana
        (1, (0x30A0, 0x30FF)),   # Katakana
    ]
    combining = [0x0300, 0x0301, 0x0302, 0x0308, 0x034F]
    out = []
    for _ in range(length):
        if rng.random() < 0.08:
            out.append(_weighted_choice(rng, [
                (3, ' '), (3, '-'), (2, '_'), (2, '.'), (1, '#'), (1, '+')
            ]))
            continue
        lo, hi = _weighted_choice(rng, pools)
        cp = rng.randint(lo, hi)
        # Avoid characters that commonly invalidate Windows path segments
        if cp in (0, ord('\\'), ord('/'), ord(':'), ord('*'), ord('?'), ord('"'), ord('<'), ord('>'), ord('|')):
            cp = 0x41 + rng.randint(0, 25)
        ch = chr(cp)
        out.append(ch)
        if rng.random() < 0.15:
            out.append(''.join(chr(rng.choice(combining)) for _ in range(rng.randint(1, 2))))
    seg = ''.join(out)
    seg = seg.rstrip(' .') or 'x'
    return seg

def _random_extension(rng: random.Random) -> str:
    return rng.choice([
        'txt','bin','png','jpg','mp3','rar','zip','7z','pdf','doc','xls','exe','dll','sys','tmp','log','csv','json','xml'
    ])

def _random_drive(rng: random.Random) -> str:
    return rng.choice(["C:", "D:", "E:", "Z:"])

def _random_windows_root_variants(rng: random.Random) -> str:
    # Return one of several valid Windows root prefixes
    drive = _random_drive(rng)
    return rng.choice([
        f"{drive}\\",
        f"\\\\?\\{drive}\\",
        f"\\\\.\\{drive}\\",
        "\\\\server\\share\\",  # UNC path
    ])

def _random_filename(rng: random.Random, min_segs=1, max_segs=4, want_ext=True) -> str:
    segs = [ _random_unicode_segment(rng, 1, rng.randint(3, 16)) for _ in range(rng.randint(min_segs, max_segs)) ]
    name = "\\".join(segs)  # backslash will be added by path join below
    base = _random_unicode_segment(rng, 1, rng.randint(3, 20))
    if want_ext and rng.random() < 0.85:
        base = f"{base}.{_random_extension(rng)}"
    # Combine segments using backslashes
    parts = []
    if name:
        parts.extend(segs)
    parts.append(base)
    return "\\".join(parts)

def _random_path(rng: random.Random, allow_relative=True) -> str:
    if not allow_relative or rng.random() < 0.7:
        root = _random_windows_root_variants(rng)
    else:
        root = ''
    return root + _random_filename(rng)

def _archive_filename(rng: random.Random) -> str:
    # Prefer .rar extension but allow others
    if rng.random() < 0.8:
        base = _random_unicode_segment(rng, 1, 16)
        return f"{base}.rar"
    else:
        return f"{_random_unicode_segment(rng,1,16)}.{_random_extension(rng)}"

def _compose_multi_field_blob(rng: random.Random) -> bytes:
    # Build a blob encoding several UTF-16 strings back-to-back, each NUL-terminated.
    # This suits the fuzzer which may request multiple FUZZ_PARAM_STR/FILENAME values
    # from the same initial buffer.
    fields = []
    # 1) Archive path (ANSI in stub but we provide UTF-16; harness may reinterpret bytes)
    arch = _random_path(rng)
    # Force .rar ending sometimes
    if rng.random() < 0.6 and not arch.lower().endswith('.rar'):
        if arch.endswith('\\'):
            arch += _archive_filename(rng)
        else:
            # Replace last segment's extension
            arch += ''  # keep as is
    # 2) Comment strings (two variants)
    cmt1 = _random_unicode_segment(rng, 0, 64)
    cmt2 = _random_unicode_segment(rng, 0, 64)
    # 3) Destination path and name for extract
    dpath = _random_path(rng)
    dname = _random_unicode_segment(rng, 1, 20)
    if rng.random() < 0.7:
        dname = f"{dname}.{_random_extension(rng)}"

    # Occasionally produce empty strings to exercise nullptr behavior in harness
    if rng.random() < 0.15:
        cmt1 = ''
    if rng.random() < 0.15:
        cmt2 = ''

    fields.extend([arch, cmt1, cmt2, dpath, dname])

    # Join as UTF-16LE NUL-terminated sequence
    out = b"".join(_u16le(f) for f in fields)

    # Ensure we remain within size limit; if too large, truncate at a NUL boundary
    if len(out) > MAX_BYTES:
        # Attempt to trim by removing trailing fields
        while len(out) > MAX_BYTES and fields:
            fields.pop()
            out = b"".join(_u16le(f) for f in fields)
        # If still too big, hard truncate and ensure ends with NUL
        if len(out) > MAX_BYTES:
            out = out[:MAX_BYTES-2] + b"\x00\x00"
    return out

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a strategy: single UTF-16 string or a bundle of multiple fields
    strategy = _weighted_choice(rng, [
        (3, 'single-archive'),
        (2, 'single-dest'),
        (5, 'bundle'),
    ])

    if strategy == 'single-archive':
        s = _random_path(rng)
        # Bias towards .rar filenames
        if rng.random() < 0.8:
            if s.endswith('\\'):
                s += _archive_filename(rng)
            elif not s.lower().endswith('.rar'):
                # Replace last segment's extension by appending .rar safely
                s += '' if s.lower().endswith('.rar') else ''
        data = _u16le(s)
    elif strategy == 'single-dest':
        # Destination path or name for RARProcessFileW
        if rng.random() < 0.5:
            s = _random_path(rng)
        else:
            s = _random_unicode_segment(rng, 1, 32)
            if rng.random() < 0.7:
                s = f"{s}.{_random_extension(rng)}"
        data = _u16le(s)
    else:
        data = _compose_multi_field_blob(rng)

    # Final size guard
    if len(data) > MAX_BYTES:
        data = data[:MAX_BYTES]
        # Ensure last two bytes are NUL to terminate cleanly
        if len(data) >= 2:
            data = data[:-2] + b"\x00\x00"
        else:
            data = b"\x00\x00"
    return data
